namespace FaizaCash.Domain;
public class User { public Guid Id { get; set; } = Guid.NewGuid(); public string Login { get; set; } = ""; public string PasswordHash { get; set; } = ""; public string FullName { get; set; } = ""; public bool Active { get; set; } = true; public bool MustChangePassword { get; set; } = true; public List<UserRole> UserRoles { get; set; } = []; }
public class Role { public short Id { get; set; } public string Code { get; set; } = ""; public string Name { get; set; } = ""; }
public class UserRole { public Guid UserId { get; set; } public short RoleId { get; set; } public User User { get; set; } = null!; public Role Role { get; set; } = null!; }
public class RefreshToken { public Guid Id { get; set; } = Guid.NewGuid(); public Guid UserId { get; set; } public User User { get; set; } = null!; public string Hash { get; set; } = ""; public DateTime ExpiresAt { get; set; } public DateTime? RevokedAt { get; set; } public Guid? ReplacedBy { get; set; } }
public class LoginAttempt { public long Id { get; set; } public string Login { get; set; } = ""; public string Ip { get; set; } = ""; public bool Succeeded { get; set; } public DateTime CreatedAt { get; set; } = DateTime.UtcNow; }
public class Currency { public short Id { get; set; } public string Code { get; set; } = ""; public string Name { get; set; } = ""; public byte MinorUnits { get; set; } = 2; }
public class Branch { public long Id { get; set; } public string Code { get; set; } = ""; public string Name { get; set; } = ""; public string City { get; set; } = ""; public bool Active { get; set; } = true; }
public class Cashbox { public long Id { get; set; } public string Code { get; set; } = ""; public string Name { get; set; } = ""; public long BranchId { get; set; } public Branch Branch { get; set; } = null!; public short CurrencyId { get; set; } public Currency Currency { get; set; } = null!; public decimal? BalanceLimit { get; set; } public bool Active { get; set; } = true; public CashboxOpening? Opening { get; set; } }
public class CashboxOpening { public long Id { get; set; } public long CashboxId { get; set; } public Cashbox Cashbox { get; set; } = null!; public DateOnly Date { get; set; } public decimal Amount { get; set; } public Guid CreatedBy { get; set; } }
public class Category { public long Id { get; set; } public string Type { get; set; } = ""; public long? ParentId { get; set; } public string Name { get; set; } = ""; public bool Active { get; set; } = true; /// <summary>Системная категория (межкассовый перевод): не переименовывается, не архивируется, в документах вручную не используется.</summary>
    public bool IsSystem { get; set; } }
public class Counterparty { public long Id { get; set; } public string Name { get; set; } = ""; public string Kind { get; set; } = "other"; public string? TaxCode { get; set; } public string? Contact { get; set; } public bool Active { get; set; } = true; }
public class Settlement { public long Id { get; set; } public long? CashboxId { get; set; } public Cashbox? Cashbox { get; set; } public long CounterpartyId { get; set; } public Counterparty Counterparty { get; set; } = null!; public string? CounterpartyNameSnapshot { get; set; } public Guid? RepresentativeId { get; set; } public string Direction { get; set; } = "receivable"; public string BasisType { get; set; } = "manual"; public string BasisReference { get; set; } = ""; public decimal TotalAmount { get; set; } public decimal PaidAmount { get; set; } public string Status { get; set; } = "open"; public DateOnly DueDate { get; set; } public DateTime CreatedAt { get; set; } = DateTime.UtcNow; public List<PaymentAllocation> Allocations { get; set; } = []; }
public class PaymentAllocation { public long Id { get; set; } public long SettlementId { get; set; } public Settlement Settlement { get; set; } = null!; public long OperationId { get; set; } public CashOperation Operation { get; set; } = null!; public decimal Amount { get; set; } public DateTime CreatedAt { get; set; } = DateTime.UtcNow; public Guid CreatedBy { get; set; } }
public class DocumentType { public short Id { get; set; } public string Code { get; set; } = ""; public string Name { get; set; } = ""; public bool Active { get; set; } = true; }
public class CashOperation { public long Id { get; set; } public long CashboxId { get; set; } public DateOnly Date { get; set; } public string Type { get; set; } = ""; public string Status { get; set; } = "draft"; public decimal Amount { get; set; } public string Description { get; set; } = ""; public long CategoryId { get; set; } public Category Category { get; set; } = null!; public long? CounterpartyId { get; set; } public Counterparty? Counterparty { get; set; } public string? OrganizationNameSnapshot { get; set; } public string? CashboxNameSnapshot { get; set; } public string? CashboxCodeSnapshot { get; set; } public string? CategoryNameSnapshot { get; set; } public string? CounterpartyNameSnapshot { get; set; } public short? DocumentTypeId { get; set; } public string? DocumentNumber { get; set; } public long? ShiftId { get; set; } public long? PostingSeq { get; set; } public bool IsReversal { get; set; } public long? ReversalOfId { get; set; } public long? ReversalId { get; set; } public string? ReversalReason { get; set; } public long? TransferId { get; set; } public CashTransfer? Transfer { get; set; } public Guid RequestKey { get; set; } = Guid.NewGuid(); public Guid CreatedBy { get; set; } public User Author { get; set; } = null!; public Guid? PostedBy { get; set; } public DateTime? PostedAt { get; set; } public DateTime CreatedAt { get; set; } = DateTime.UtcNow; public DateTime UpdatedAt { get; set; } = DateTime.UtcNow; public int Version { get; set; } = 1;
    /// <summary>Согласование расхода: none | pending | approved | rejected.</summary>
    public string ApprovalStatus { get; set; } = "none"; public Guid? ApprovedBy { get; set; } public DateTime? ApprovedAt { get; set; } public string? ApprovalComment { get; set; } }
public class CashTransfer { public long Id { get; set; } public long SourceCashboxId { get; set; } public long TargetCashboxId { get; set; } public DateOnly Date { get; set; } public decimal Amount { get; set; } public string Description { get; set; } = ""; public Guid RequestKey { get; set; } = Guid.NewGuid(); public Guid CreatedBy { get; set; } public DateTime CreatedAt { get; set; } = DateTime.UtcNow; public long? SourceOperationId { get; set; } public long? TargetOperationId { get; set; } }
public class RepresentativeReceipt { public long Id { get; set; } public Guid RepresentativeId { get; set; } public long CounterpartyId { get; set; } public Counterparty Counterparty { get; set; } = null!; public string BasisType { get; set; } = "order"; public string BasisReference { get; set; } = ""; public decimal Amount { get; set; } public long CashboxId { get; set; } public string Status { get; set; } = "collected"; public Guid RequestKey { get; set; } = Guid.NewGuid(); public Guid CreatedBy { get; set; } public DateTime CreatedAt { get; set; } = DateTime.UtcNow; public DateTime? HandedOverAt { get; set; } public Guid? AcceptedBy { get; set; } public DateTime? AcceptedAt { get; set; } }
public class DocumentSequence { public long CashboxId { get; set; } public string Type { get; set; } = ""; public short Year { get; set; } public int LastNumber { get; set; } }
public class CashShift { /// <summary>Пересчёт наличных по номиналам при закрытии (необязателен).</summary>
    public List<DenominationCount>? Denominations { get; set; } public long Id { get; set; } public long CashboxId { get; set; } public DateOnly Date { get; set; } public string Status { get; set; } = "open"; public decimal OpeningBalance { get; set; } public decimal? ClosingBalance { get; set; } public decimal? ClosingDifference { get; set; } public Guid OpenedBy { get; set; } public Guid? ClosedBy { get; set; } public DateTime OpenedAt { get; set; } = DateTime.UtcNow; public DateTime? ClosedAt { get; set; } }
public class AuditEvent { public long Id { get; set; } public Guid? UserId { get; set; } public string Action { get; set; } = ""; public string Entity { get; set; } = ""; public long? EntityId { get; set; } public string Details { get; set; } = "{}"; public DateTime CreatedAt { get; set; } = DateTime.UtcNow; }
public class NotificationRead { public Guid UserId { get; set; } public string NotificationKey { get; set; } = ""; public DateTime ReadAt { get; set; } = DateTime.UtcNow; }

public class CashAccess { public Guid UserId { get; set; } public long CashboxId { get; set; } }
public class Organization { public int Id { get; set; } = 1; public string Name { get; set; } = "ООО «Фаиза»"; public string Currency { get; set; } = "TJS"; public string TimeZone { get; set; } = "Asia/Dushanbe";
    /// <summary>Порог согласования расходов; null — согласование выключено.</summary>
    public decimal? ExpenseApprovalThreshold { get; set; } }

/// <summary>Вложение (скан/фото первичного документа). Файл хранится на диске под именем Id, без пользовательского имени в пути.</summary>
public class Attachment { public Guid Id { get; set; } = Guid.NewGuid(); public string OwnerType { get; set; } = ""; public long OwnerId { get; set; } public long CashboxId { get; set; } public string FileName { get; set; } = ""; public string ContentType { get; set; } = ""; public long SizeBytes { get; set; } public string Sha256 { get; set; } = ""; public Guid UploadedBy { get; set; } public DateTime UploadedAt { get; set; } = DateTime.UtcNow; }

/// <summary>Аванс подотчётному лицу (контрагент вида employee): выдаётся проведённым РКО, закрывается отчётом и возвратом/возмещением.</summary>
public class Advance { public long Id { get; set; } public long OperationId { get; set; } public long CashboxId { get; set; } public long CounterpartyId { get; set; } public Counterparty Counterparty { get; set; } = null!; public decimal Amount { get; set; } public string Purpose { get; set; } = ""; public DateOnly IssueDate { get; set; } public DateOnly DueDate { get; set; } public string Status { get; set; } = "issued"; public decimal? Spent { get; set; } public long? SettlementOperationId { get; set; } public Guid CreatedBy { get; set; } public DateTime CreatedAt { get; set; } = DateTime.UtcNow; public Guid? ReportedBy { get; set; } public DateTime? ReportedAt { get; set; } public Guid? ClosedBy { get; set; } public DateTime? ClosedAt { get; set; } public List<AdvanceReportLine> Lines { get; set; } = []; }
public class AdvanceReportLine { public long Id { get; set; } public long AdvanceId { get; set; } public DateOnly Date { get; set; } public string Description { get; set; } = ""; public decimal Amount { get; set; } public long CategoryId { get; set; } public Category Category { get; set; } = null!; }

/// <summary>Строка пересчёта наличных по номиналам. Сумма считается только в decimal.</summary>
public sealed record DenominationCount(decimal Value, string? Kind, int Count)
{
    public decimal Total => Value * Count;
}
/// <summary>Номинал банкноты или монеты (справочник, сидируется миграцией по данным НБТ).</summary>
public class Denomination { public int Id { get; set; } public string Currency { get; set; } = "TJS"; public decimal Value { get; set; } public string Kind { get; set; } = "banknote"; public bool Active { get; set; } = true; }
/// <summary>Акт инвентаризации наличных денежных средств. Неизменяем (append-only, триггер БД).</summary>
public class CashInventory { public long Id { get; set; } public long CashboxId { get; set; } public DateOnly Date { get; set; } public DateTime CountedAt { get; set; } = DateTime.UtcNow; public decimal ExpectedBalance { get; set; } public decimal ActualBalance { get; set; } public decimal Difference { get; set; } public List<DenominationCount> Denominations { get; set; } = []; public string[] Commission { get; set; } = []; public string? Note { get; set; } public Guid CreatedBy { get; set; } }
